import{_ as t,o as s,c as o,a2 as a}from"./chunks/framework.D1JEzK2q.js";const p=JSON.parse('{"title":"Streaming API (SSE)","description":"","frontmatter":{},"headers":[],"relativePath":"api/streaming.md","filePath":"api/streaming.md"}'),n={name:"api/streaming.md"};function i(r,e,d,h,c,l){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="streaming-api-sse" tabindex="-1">Streaming API (SSE) <a class="header-anchor" href="#streaming-api-sse" aria-label="Permalink to &quot;Streaming API (SSE) {#streaming-api-sse}&quot;">​</a></h1><p>Set <code>&quot;stream&quot;: true</code> in the request body to receive a Server-Sent Events stream.</p><p>With semantic conversation intake enabled, contextual task acknowledgements also arrive as <code>text_delta</code> events before task execution, including web continuations of channel sessions. Acknowledgements belong to the requesting input; they do not consume pending reports from earlier tasks. Incomplete-material turns can finish with empty text while retaining their input history. See <a href="/claude-gateway/guide/orchestration.html">conversation intake configuration</a> for the configurable waiting interval.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: my-secret-key&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;message&quot;: &quot;Explain this code&quot;, &quot;chat_id&quot;: &quot;myapp&quot;, &quot;stream&quot;: true}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:10850/api/v1/agents/alfred/messages</span></span></code></pre></div><p><strong>Response:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data: {&quot;type&quot;:&quot;text_delta&quot;,&quot;text&quot;:&quot;Let me&quot;,&quot;seq&quot;:1}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;text_delta&quot;,&quot;text&quot;:&quot; explain...&quot;,&quot;seq&quot;:2}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;tool_use&quot;,&quot;name&quot;:&quot;Read&quot;,&quot;id&quot;:&quot;toolu_abc123&quot;,&quot;seq&quot;:3}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;text_delta&quot;,&quot;text&quot;:&quot;Here&#39;s the explanation...&quot;,&quot;seq&quot;:4}</span></span>
<span class="line"><span>data: {&quot;type&quot;:&quot;result&quot;,&quot;text&quot;:&quot;Here&#39;s the full explanation...&quot;,&quot;seq&quot;:5,&quot;request_id&quot;:&quot;550e8400-...&quot;,&quot;session_id&quot;:&quot;abc-123&quot;,&quot;duration_ms&quot;:4200}</span></span>
<span class="line"><span>data: [DONE]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; When images are captured during the turn, the \`result\` event also includes \`&quot;attachments&quot;: [{&quot;type&quot;:&quot;image&quot;,&quot;url&quot;:&quot;...&quot;}]\`.</span></span></code></pre></div><blockquote><p><code>seq</code> is the event&#39;s position <strong>within this turn</strong>, counting from 1 — it restarts at 1 on the next turn, so it is a cursor only in combination with the turn&#39;s <code>request_id</code>. Remember both: they are what <a href="/claude-gateway/api/streaming.html#resuming-an-interrupted-stream">resuming an interrupted stream</a> takes. (<code>data: [DONE]</code> is a stream terminator, not an event, and carries neither.)</p></blockquote><h2 id="requests-with-tool-use" tabindex="-1">Requests with tool use <a class="header-anchor" href="#requests-with-tool-use" aria-label="Permalink to &quot;Requests with tool use {#requests-with-tool-use}&quot;">​</a></h2><p>Tool access is resolved from the agent&#39;s explicit <code>allow_tools</code> value, falling back to the API key&#39;s <code>allow_tools</code> flag when the agent value is unset. This applies to sync and streaming requests. No request-body field grants tool access.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: automation-key-789&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;message&quot;: &quot;Run the setup script in /workspace and report the output&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;chat_id&quot;: &quot;myapp&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;stream&quot;: true,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;timeout_ms&quot;: 120000</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:10850/api/v1/agents/alfred/messages</span></span></code></pre></div><blockquote><p>When the effective <code>allow_tools</code> value is false, requests remain conversational. The request body cannot enable tools.</p></blockquote><p><strong>Workspace identity files are always protected in API sessions.</strong> Regardless of <code>allow_tools</code>, the agent will not create or update workspace identity files (<code>AGENTS.md</code>, <code>SOUL.md</code>, <code>MEMORY.md</code>, <code>CLAUDE.md</code>, <code>IDENTITY.md</code>, <code>USER.md</code>, <code>HEARTBEAT.md</code>) during an API session. If asked to remember something, the agent will decline. Memory updates require a Telegram or Cron session where the agent has full workspace access.</p><p><strong>Event types:</strong></p><blockquote><p><strong>⚠️ Breaking change — the soft timeout is no longer terminal.</strong> Up to and including 1.8.2, a turn that passed <code>timeout_ms</code> emitted a terminal <code>{&quot;type&quot;:&quot;error&quot;,&quot;message&quot;:&quot;Agent response timeout&quot;}</code> and the stream ended there. It now emits a <strong>non-terminal</strong> <code>timeout</code> event instead, and the connection stays open until the turn finishes or the hard cap (a further 10 minutes) fires.</p><p>A client written against 1.8.2 or earlier that ignores unknown event types will not fail at <code>timeout_ms</code> any more — it will sit on an open connection for up to 10 extra minutes waiting for a terminal frame. <strong>Handle <code>timeout</code> explicitly</strong>: render it as &quot;still working&quot;, and if you need the old cut-off, close the connection yourself when you receive it (the turn keeps running server-side and its reply is still persisted to history; you can read it back via <a href="/claude-gateway/api/streaming.html#resuming-an-interrupted-stream"><code>GET …/stream</code></a> or from the session history).</p></blockquote><p>Every event in the table below carries a <code>seq</code> — the turn-scoped sequence number described above — in addition to its own fields. The <code>data: [DONE]</code> line that closes the stream is a terminator, not an event, and has no fields at all.</p><table tabindex="0"><thead><tr><th>Type</th><th>Fields</th><th>Terminal</th><th>Description</th></tr></thead><tbody><tr><td><code>text_delta</code></td><td><code>text</code></td><td>no</td><td>Incremental text chunk</td></tr><tr><td><code>tool_use</code></td><td><code>name</code>, <code>id</code></td><td>no</td><td>Tool invocation (e.g. Read, Grep, Bash)</td></tr><tr><td><code>thinking</code></td><td><code>text</code></td><td>no</td><td>Agent reasoning (if available)</td></tr><tr><td><code>timeout</code></td><td><code>message</code>, <code>resumable: true</code></td><td><strong>no</strong></td><td>The soft response budget elapsed, but the turn is still running — see below</td></tr><tr><td><code>result</code></td><td><code>text</code>, <code>request_id</code>, <code>session_id</code>, <code>duration_ms</code>, <code>attachments?</code></td><td>yes</td><td>Final aggregated result; <code>attachments</code> present only when images were captured</td></tr><tr><td><code>error</code></td><td><code>message</code>, <code>code?</code></td><td>yes</td><td>The turn failed</td></tr></tbody></table><p>The stream ends with <code>data: [DONE]</code> after <code>result</code>.</p><p><strong>Idle streams send a keepalive.</strong> While a turn is working without producing events — a long tool call, a slow model — the connection emits an SSE comment line (<code>: keepalive</code>) every 15 seconds so a reverse proxy does not close it as idle. Comment lines are discarded by every conforming SSE parser, carry no <code>seq</code>, and never reach your event handler; if you parse the stream by hand, ignore any line that starts with <code>:</code>.</p><p><strong><code>timeout</code> is not a failure.</strong> It means the turn passed <code>timeout_ms</code> without finishing; the connection stays open and the turn keeps streaming, because the subprocess is still working and its reply will still be persisted to history. Render it as &quot;still working&quot;, not as an error. Only <code>error</code> is a failure — that includes the hard cap (a further 10 minutes), at which point the turn really is abandoned.</p><p><strong>Branch on <code>code</code>, not on <code>message</code>.</strong> An <code>error</code> event carries the originating failure&#39;s code when it has one. The field is omitted when there is no code, so treat it as optional. It is present on replayed frames too, so a client that resumed through <a href="/claude-gateway/api/streaming.html#resuming-an-interrupted-stream"><code>GET …/stream</code></a> learns exactly what the original connection would have.</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>Meaning</th><th>Is the turn still running?</th></tr></thead><tbody><tr><td><code>TIMEOUT</code></td><td>The hard cap fired; the turn was interrupted with <code>SIGINT</code></td><td><strong>No</strong> — it is dead</td></tr><tr><td><code>TIMEOUT_SOFT</code></td><td>The caller&#39;s <code>timeout_ms</code> elapsed on an endpoint that cannot keep streaming the turn</td><td><strong>Yes</strong> — its reply will land in history</td></tr><tr><td><code>PROCESS_EXITED</code></td><td>The subprocess crashed mid-turn</td><td>No</td></tr></tbody></table><p><code>TIMEOUT</code> and <code>TIMEOUT_SOFT</code> are deliberately distinct: the two describe opposite situations and their messages differ only by a tense and a full stop (<code>Agent response timed out.</code> vs <code>Agent response timeout</code>), which is exactly the kind of string-matching this field exists to replace.</p><p><strong>Which endpoints emit which timeout:</strong></p><table tabindex="0"><thead><tr><th>Endpoint</th><th>At <code>timeout_ms</code></th><th>Hard cap</th><th>Resumable</th></tr></thead><tbody><tr><td><code>POST …/messages</code> with <code>stream: true</code></td><td>non-terminal <code>timeout</code> event, connection stays open</td><td>yes, +10 min → <code>error</code> / <code>TIMEOUT</code></td><td>yes, via <code>GET …/stream</code></td></tr><tr><td><code>POST …/messages</code> (synchronous)</td><td><code>504</code> response</td><td>yes, +10 min (server-side only)</td><td>no</td></tr><tr><td>Cross-channel live view (<code>POST …/chats/:chatId/sessions/:sessionId/messages</code>)</td><td>terminal <code>error</code> / <code>TIMEOUT_SOFT</code></td><td><strong>none</strong></td><td>no</td></tr></tbody></table><p>The cross-channel live view keeps the pre-#421 behaviour on purpose: it has no resume endpoint to reconnect through, so holding the connection open would buy nothing. Its turn is <em>abandoned</em>, never interrupted — the agent keeps working and the reply appears in the session history. Poll history, or start a fresh turn.</p><p><strong>What the hard cap does.</strong> At the cap the turn is <em>interrupted</em>, not merely abandoned: the subprocess is sent <code>SIGINT</code> so it stops working and stops consuming tokens. History gets exactly one assistant row for that turn — any text the turn had already streamed, followed by <code>⚠️ Agent response timed out.</code> A hard-capped turn never produces a later reply, so it can never leave both a failure row and a reply row behind.</p><h2 id="resuming-an-interrupted-stream" tabindex="-1">Resuming an interrupted stream <a class="header-anchor" href="#resuming-an-interrupted-stream" aria-label="Permalink to &quot;Resuming an interrupted stream {#resuming-an-interrupted-stream}&quot;">​</a></h2><p>A streamed turn is no longer bound to the request that started it. If the connection drops — a browser reload, a flaky mobile network, a proxy idle timeout — the turn keeps running server-side and its events keep being buffered, so a new connection can pick it up where the old one left off.</p><h3 id="get-apiv1agentsagentidsessionssessionidstream" tabindex="-1">GET /api/v1/agents/:agentId/sessions/:sessionId/stream <a class="header-anchor" href="#get-apiv1agentsagentidsessionssessionidstream" aria-label="Permalink to &quot;GET /api/v1/agents/:agentId/sessions/:sessionId/stream {#get-apiv1agentsagentidsessionssessionidstream}&quot;">​</a></h3><p>Re-attach to the session&#39;s current turn. Replays every buffered event after the cursor, then keeps streaming live events on the same connection, terminating with the same <code>result</code> + <code>[DONE]</code> frames the original connection would have got.</p><table tabindex="0"><thead><tr><th>Query param</th><th>Description</th></tr></thead><tbody><tr><td><code>after_seq</code></td><td>Resume after this sequence number. Omit (or <code>0</code>) to replay the turn from its first event.</td></tr><tr><td><code>request_id</code></td><td>The turn you mean to resume — the <code>request_id</code> its frames carry. <strong>Required whenever <code>after_seq &gt; 0</code></strong>; optional when replaying from the start, and the frames you get back report the turn&#39;s own <code>request_id</code> either way.</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># The stream died after seq 12 — pick the same turn back up.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -N</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-Api-Key: my-secret-key&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;http://localhost:10850/api/v1/agents/alfred/sessions/abc-123/stream?after_seq=12&amp;request_id=req-abc&quot;</span></span></code></pre></div><p>Read access is enough — resuming a turn reads it, it does not start one.</p><p><strong>A cursor without a <code>request_id</code> is not a resume.</strong> Sequence numbers restart at 1 for every turn, so <code>after_seq=12</code> alone does not say <em>which</em> turn&#39;s twelfth event you saw. If the session has moved on to a later turn, that cursor lands inside it and would replay a stream you were never watching, with everything before seq 12 silently missing. The endpoint answers <code>400</code> instead: send the <code>request_id</code> from the frames you received, or drop <code>after_seq</code> and replay the current turn from its first event.</p><p><strong>A client that reloaded has no <code>request_id</code>, and that is fine.</strong> Drop <code>after_seq</code>, and the frames you get back carry the turn&#39;s own <code>request_id</code> — which is what you feed to the next resume, cursor and all.</p><p><strong>Resuming is never a conflict.</strong> <code>409</code> still means &quot;you tried to start a second turn on a busy session&quot;; it is never the answer to a resume. When a turn cannot be resumed the endpoint answers <code>410 Gone</code> with a <code>code</code> saying why:</p><table tabindex="0"><thead><tr><th><code>code</code></th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td><code>TURN_GONE</code></td><td>No turn for that session — it never ran, or it finished more than 2 minutes ago</td><td>Read the session&#39;s history</td></tr><tr><td><code>TURN_MISMATCH</code></td><td>The session has a turn, but not the <code>request_id</code> you asked for — yours is over</td><td>Read the session&#39;s history</td></tr><tr><td><code>TURN_TRUNCATED</code></td><td>That cursor&#39;s events have been evicted (see the buffer limits below) — only a non-zero <code>after_seq</code> can get this</td><td>Retry <strong>without</strong> <code>after_seq</code></td></tr><tr><td><code>CURSOR_AHEAD</code></td><td><code>after_seq</code> is past the turn&#39;s last event</td><td>Retry <strong>without</strong> <code>after_seq</code></td></tr></tbody></table><p>Each response carries a <code>hint</code> field with the same advice.</p><p><strong><code>CURSOR_AHEAD</code> and <code>TURN_TRUNCATED</code> are the two you can recover from without history.</strong> Both mean the turn is live and only your <em>cursor</em> is unusable — past the turn&#39;s last event, or pointing into events the buffer has already dropped. The answer to either is the same: drop <code>after_seq</code> and call again.</p><p>A completed turn stays replayable for <strong>2 minutes</strong> after its terminal frame, which is what makes a reload immediately after the answer arrives still work. The replayed <code>result</code> frame reports <code>duration_ms</code> for the turn itself, not for the time since you reconnected.</p><p><strong>Starting a new turn ends the previous one&#39;s grace window immediately.</strong> A session holds at most one turn: the moment a new turn starts, the completed one is dropped, even if less than 2 minutes have passed. So if two clients share a <code>session_id</code> — a phone reloading to resume turn <em>N</em> while a laptop has already posted turn <em>N+1</em> — the reload gets <code>TURN_MISMATCH</code> rather than the replay the grace window otherwise promises. Read the session&#39;s history for that turn&#39;s result; the reply was persisted regardless. Give each client its own session — one <a href="/claude-gateway/api/sessions.html#post-apiv1agentsagentidsessions"><code>POST /sessions</code></a> each — if you need their turns to be independently resumable.</p><p>The buffer is bounded per turn — 2,000 events or ~4 MB, whichever comes first — and once the oldest events are evicted, a cursor pointing into the evicted region gets <code>TURN_TRUNCATED</code> rather than a replay with a silent hole in it. Replaying from the start (no <code>after_seq</code>) is never refused, though: you get the oldest event still buffered onwards, and the first frame&#39;s <code>seq</code> tells you how much of the turn came before it. Nothing is actually lost — the terminal <code>result</code> carries the turn&#39;s full text regardless of how much of the delta stream survived.</p><hr>`,43)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
